with open("agent_data/texts.json", "r", encoding="utf-8") as f:
    texts = json.load(f)

print(f"Было документов: {len(texts)}")

existing = set(texts)
added = 0
for article in general_articles:
    if article not in existing:
        texts.append(article)
        added += 1

with open("agent_data/texts.json", "w", encoding="utf-8") as f:
    json.dump(texts, f, ensure_ascii=False, indent=2)

print(f"Добавлено: {added}")
print(f"Стало документов: {len(texts)}")